// One flat item for the CRM nodes: who, what happened, and the text a person reads.
const body = $input.first().json.body;
const p = body.prospect || {};
const r = body.result || {};
const call = body.call || {};
const summary = r.summary || {};
return [{
  json: {
    event_id: body.event_id,
    event: body.event,
    occurred_at: body.occurred_at,
    phone: p.phone_normalized || p.phone || '',
    email: p.email || '',
    first_name: p.first_name || '',
    last_name: p.last_name || '',
    company: p.company || '',
    disposition: r.disposition,
    reached: r.reached,
    qualification: r.qualification_status,
    interest: r.interest_level,
    next_action: r.next_action,
    duration_seconds: r.duration_seconds,
    summary_text: r.summary_text || '',
    what_happened: summary.what_happened || '',
    next_step: summary.next_step || '',
    pain_points: (r.pain_points || []).join('; '),
    objections: (r.objections || []).map(o => `${o.kind || ''}: ${o.detail || ''}`).join('; '),
    meeting_start: r.meeting_start,
    callback_for: r.callback_scheduled_for,
    do_not_call: r.disposition === 'DO_NOT_CALL',
    call_id: call.telephony_call_id,
    attempt_id: r.call_attempt_id,
    call_at_ms: call.ended_at ? Date.parse(call.ended_at) : Date.now(),
  },
}];

// Whichever branch ran, carry the contact id forward.
const item = $input.first().json;
const contactId = item.id || (item.results && item.results[0] && item.results[0].id);
return [{ json: { contactId } }];

